/** Table D-5 ??? 2024 staffing delay minutes concentration */
export const STAFFING_FACILITIES_2024 = [
  { id: "EWR", name: "Newark Liberty", type: "Tower/TRACON", minutes: 226_370, fillRatePct: 87 },
