# Prepend post via Node to avoid huge PowerShell here-string issues
node -e "
const fs = require('fs');
const path = 'src/data/posts.ts';
let s = fs.readFileSync(path, 'utf8');
const marker = 'export const samplePosts: Post[] = [';
const idx = s.indexOf(marker);
if (idx < 0) throw new Error('marker not found');
const insertAt = idx + marker.length;
const entry = fs.readFileSync('tmp-post-entry.txt', 'utf8');
s = s.slice(0, insertAt) + '\n' + entry + s.slice(insertAt);
fs.writeFileSync(path, s);
console.log('inserted', entry.length);
"

