  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ANNUAL_BY_CAUSE,
  BTS_CAUSE_MINUTES_2024,
  CAUSE_META,
  DUAL_LENS_2024,
  FACILITY_BUCKETS_2022_24,
